6	export type CreateBusinessState = { error: string | null };
7	
8	export async function createBusiness(
9	  _prevState: CreateBusinessState,
10	  formData: FormData,
11	): Promise<CreateBusinessState> {
12	  const supabase = await createClient();
13	  const {
14	    data: { user },
15	  } = await supabase.auth.getUser();
16	
17	  if (!user) {
18	    redirect("/login");
19	  }
20	
21	  const name = (formData.get("name") as string)?.trim();
22	  const businessType = formData.get("business_type") as string;
23	
24	  if (!name) {
25	    return { error: "Nama toko wajib diisi." };
26	  }
27	  if (businessType !== "fnb" && businessType !== "retail" && businessType !== "tiket") {
28	    return { error: "Pilih jenis bisnis dulu." };
29	  }
30	
31	  const { data: business, error } = await supabase
32	    .from("businesses")
33	    .insert({
34	      owner_id: user.id,
35	      name,
36	      business_type: businessType,
37	    })
38	    .select("id")
39	    .single();
40	
41	  if (error || !business) {
42	    return { error: error?.message ?? "Gagal membuat bisnis." };
43	  }
44	
45	  // Belum ada trial — pemilik baru harus pilih & bayar paket dulu sebelum
46	  // bisa masuk ke dashboard/kasir (lihat gating di layout.tsx dashboard & pos).
47	  const { error: subscriptionError } = await supabase.from("subscriptions").insert({
48	    business_id: business.id,
49	    plan_code: "",
50	    status: "unpaid",
51	  });
52	
53	  if (subscriptionError) {
54	    return { error: subscriptionError.message };
55	  }
56	
57	  redirect(`/business/${business.id}/billing`);
58	}
